{{DEFAULT_INSTRUCTIONS}}

---

## DRHP SECTION: {{SECTION_TITLE}}

{{SECTION_TEXT}}

---

## OUTPUT INSTRUCTIONS

Return ONLY a valid JSON object. Do not include markdown fences, explanation, or any text outside the JSON. Use null for any field where the document does not provide sufficient data — never fabricate numbers.

Return a JSON object with ONLY these top-level keys (omit keys you have no evidence for):

- heroHeader: {
    nineMonthRevenueCr,
    adjEbitdaMarginPct
  }

- financials: {
    revenueHistory:           [{ year, valueCr }],
    adjEbitdaHistory:         [{ year, valuePct }],
    operatingCashFlowHistory: [{ year, valueCr }],
    patWarning,
    forwardModel: [{ year, label, bearCr, baseCr, bullCr }]
  }
  patWarning: string explaining PAT anomaly or earnings quality concern (null if none)
  forwardModel[].label must be: "Revenue"|"EBITDA"|"PAT"
  forwardModel[].year: fiscal year label (e.g. "FY26E", "FY27E", "FY28E")
  Provide forwardModel rows for each of the 3 forecast years × each label (9 rows total)

- financialHistory: {
    plSummary:          [{ year, revenueCr, revenueGrowthPct, grossMarginPct, ebitdaCr, ebitdaMarginPct, patCr, patMarginPct, eps }],
    revenueCagr, ebitdaCagr, patCagr,
    balanceSheetHealth: [{ year, netDebtCr, netDebtToEbitda, interestCoverage, rocePct, roePct, currentRatio }],
    cashFlowQuality:    [{ year, cfoCr, cfoToEbitda, capexCr, fcfCr, fcfMarginPct }],
    earningsQualityConcern,
    peerBenchmarking:   [{ company, revenueCr, revenueGrowthPct, ebitdaMarginPct, rocePct, pe, evToEbitda, ps }],
    peerPositioning,
    premiumDiscountJustified
  }

- forwardModel: {
    revenueForecasts:     [{ year, bearGrowthPct, baseGrowthPct, bullGrowthPct, bearRevenueCr, baseRevenueCr, bullRevenueCr }],
    marginAssumptions:    [{ margin, historicalAvgPct, industryMedianPct, fy1Pct, fy2Pct, fy3Pct, rationale }],
    integratedPlForecast: [{ year, revenueCr, ebitdaCr, ebitCr, patCr, eps, epsGrowthPct }],
    fcfForecast:          [{ year, ebitdaCr, capexCr, fcffCr, fcfeCr }]
  }

- valuation: {
    peMethod: {
      scenarios: [{ scenario, fy1Eps, fy2Eps, fy3Eps, justifiedPe, impliedFairValue, vsIpoBandPct }]
    },
    evSalesMethod: {
      scenarios: [{ scenario, evSalesMultiple, impliedFairValue, vsIpoBandPct }]
    },
    reverseDcf: {
      wacc, terminalGrowthRate,
      scenarios: [{ label, impliedRevenueCagr10yr, impliedEbitdaMarginTerminal, verdict }]
    },
    compsTradingMultiples: [{ multiple, peerMedian, ipoImpliedLower, ipoImpliedUpper, premiumDiscountPct, justified }],
    sOtp: {
      applicable,
      segments: [{ name, metricUsed, fy2ValueCr, multipleApplied, segmentEvCr, rationale }],
      totalEvCr, netDebtCr, equityValueCr, perShareValue
    },
    valuationSummary:    [{ method, bearFairValue, baseFairValue, bullFairValue, weight }],
    weightedFairValue, ipoUpperBand, marginOfSafetyPct,
    ipoPricingScenarios: [{ scenario, impliedFairValue, vsIpoBandPct, verdict }],
    peerComparisons:     [{ company, metric, peerValue, ipoImplied, premiumDiscountPct }],
    finalPricingVerdict
  }
  reverseDcf.scenarios[].verdict must be: "Achievable"|"Aggressive"|"Unrealistic"
  peMethod.scenarios[].scenario and evSalesMethod.scenarios[].scenario and ipoPricingScenarios[].scenario must be: "Bear"|"Base"|"Bull"
  finalPricingVerdict: 1-2 sentence summary of overall valuation conclusion
